import (
	"fmt"
	"reflect"
	"regexp"

	"github.com/sirupsen/logrus"
)

// Hook is a logrus hook for redacting information from logs
type Hook struct {
	// Messages with a log level not contained in this array
	// will not be dispatched. If empty, all messages will be dispatched.
	AcceptedLevels []logrus.Level
	RedactionList  []string
	redactionKeys  []*regexp.Regexp
}

// Levels returns the user defined AcceptedLevels
// If AcceptedLevels is empty, all logrus levels are returned
func (h *Hook) Levels() []logrus.Level {
	if len(h.AcceptedLevels) == 0 {
		return logrus.AllLevels
	}
	return h.AcceptedLevels
}

// Fire redacts values in an log Entry that match
// with keys defined in the RedactionList
func (h *Hook) Fire(e *logrus.Entry) error {
	if err := h.initRedaction(); err != nil {
		return err
	}
	for _, re := range h.redactionKeys {
		// Redact based on key matching in Data fields
		for k, v := range e.Data {
			if re.MatchString(k) {
				e.Data[k] = "[REDACTED]"
				continue
			}

			e.Data[k] = redactValue(v, re)
		}

		// Redact based on text matching in the Message field
		e.Message = re.ReplaceAllString(e.Message, "$1[REDACTED]$2")
	}

	return nil
}

// redactValue walks map values while retaining their keys and applies the
// pattern to other values using Go's default string representation.
func redactValue(v interface{}, re *regexp.Regexp) interface{} {
	if v == nil {
		return nil
	}
	value := reflect.ValueOf(v)
	if value.Kind() == reflect.Map {
		if value.IsNil() {
			return v
		}
		keys := value.MapKeys()
		values := make([]interface{}, len(keys))
		resultType := value.Type()
		for i, key := range keys {
			if re.MatchString(fmt.Sprint(key.Interface())) {
				values[i] = "[REDACTED]"
			} else {
				values[i] = redactValue(value.MapIndex(key).Interface(), re)
			}
			if values[i] != nil && !reflect.TypeOf(values[i]).AssignableTo(resultType.Elem()) {
				resultType = reflect.MapOf(resultType.Key(), reflect.TypeOf((*interface{})(nil)).Elem())
			}
		}
		result := reflect.MakeMapWithSize(resultType, len(keys))
		for i, key := range keys {
			item := reflect.Zero(resultType.Elem())
			if values[i] != nil {
				item = reflect.ValueOf(values[i])
			}
			result.SetMapIndex(key, item)
		}
		return result.Interface()
	}
	str, ok := v.(string)
	if !ok {
		str = fmt.Sprint(v)
	}
	redacted := re.ReplaceAllString(str, "$1[REDACTED]$2")
	if ok || redacted != str {
		return redacted
	}
	return v
}

func (h *Hook) initRedaction() error {
	if len(h.redactionKeys) == 0 {
		for _, redactionKey := range h.RedactionList {
			re, err := regexp.Compile(redactionKey)
			if err != nil {
				return err
			}
			h.redactionKeys = append(h.redactionKeys, re)
		}
	}
	return nil
}

func (h *Hook) redact(msg string) (string, error) {
	if err := h.initRedaction(); err != nil {
		return msg, err
	}
	for _, re := range h.redactionKeys {
		msg = re.ReplaceAllString(msg, "$1[REDACTED]$2")
	}

	return msg, nil
}
